/*
 * A145061  Number of pairs of odd numbers that separate two consecutive twin
 *          prime pairs.
 * https://oeis.org/A145061
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (A001359(n+1) - (A001359(n) + 2))/2 where A001359(n) is
 *            the lower member of the nth twin‑prime pair. The sequence is
 *            generated by sieving primes and collecting twin pairs (allowing
 *            overlaps)
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "../utils/seq_realloc.h"

/* Static state */
static idx_t sieve_limit = 0;            /* current upper bound of sieve          */
static uint8_t *sieve = NULL;            /* sieve array (0 = prime, 1 = composite)*/
static idx_t scan_from = 3;              /* first odd to start scanning             */
static size_t twin_count = 0;            /* number of twin prime pairs found       */
static size_t twin_cap   = 0;            /* capacity of twin_start array           */
static seq_t *twin_start = NULL;        /* array of lower members of twin pairs   */

/* Ensure at least `required` twin primes are in twin_start. */
static void ensure_twin_primes(idx_t required)
{
    while (twin_count < required) {
        /* Expand sieve limit (doubling strategy). */
        idx_t new_limit = (sieve_limit == 0) ? 1000 : sieve_limit * 2;
        if (new_limit <= sieve_limit) new_limit = sieve_limit + 1000;

        /* Allocate new sieve array with all zeros. */
        uint8_t *new_sieve = (uint8_t*)malloc((size_t)(new_limit + 1));
        if (!new_sieve) return;                     /* OOM – caller will handle */
        memset(new_sieve, 0, (size_t)(new_limit + 1));

        if (sieve) {
            memcpy(new_sieve, sieve, (size_t)(sieve_limit + 1));
            free(sieve);
        }
        sieve = new_sieve;

        /* Eratosthenes sieve up to new_limit. */
        for (idx_t i = 2; i * i <= new_limit; ++i) {
            if (!sieve[i]) {
                for (idx_t j = i * i; j <= new_limit; j += i)
                    sieve[j] = 1;
            }
        }

        /* Scan for twin primes in the new interval. */
        for (idx_t i = scan_from; i + 2 <= new_limit; i += 2) {
            if (!sieve[i] && !sieve[i + 2]) {
                if (twin_count == twin_cap) {
                    size_t new_cap = twin_cap ? twin_cap * 2 : 32;
                    seq_t *tmp = seq_realloc(twin_start, twin_cap, new_cap);
                    if (!tmp) return;                 /* OOM – caller will handle */
                    twin_start = tmp;
                    twin_cap   = new_cap;
                }
                twin_start[twin_count++] = (seq_t)i;
            }
        }

        /* Prepare for next expansion. */
        scan_from = new_limit + 1;
        if ((scan_from & 1) == 0) ++scan_from;
        sieve_limit = new_limit;
    }
}

seq_t a(idx_t n)
{
    /* Offset 1: a(1) = 0. */
    if (n < 2) return 0;

    /* Need at least n+1 twin pairs to compute a(n). */
    ensure_twin_primes(n + 1);

    seq_t p_n     = twin_start[n - 1];
    seq_t p_next  = twin_start[n];
    seq_t diff    = p_next - p_n - (seq_t)2;
    return diff / (seq_t)2;
}
